from more import LANGS2, T2
for k in T:
    assert k in T2, ("missing in more.py", k)
def esc(s): return s.replace("\\", "\\\\").replace('"', '\\"')
base = os.path.dirname(os.path.abspath(__file__))
for i, lang in enumerate(LANGS):
    d = os.path.join(base, f"{lang}.lproj"); os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
        for k, v in T.items(): f.write(f'"{esc(k)}" = "{esc(v[i])}";\n')
print(len(T), "keys x", len(LANGS), "languages")

# second batch (+ zh-HK as a copy of zh-Hant)
for i, lang in enumerate(LANGS2):
    for out in ([lang, "zh-HK"] if lang == "zh-Hant" else [lang]):
        d = os.path.join(base, f"{out}.lproj"); os.makedirs(d, exist_ok=True)
        with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
            for k in T: f.write(f'"{esc(k)}" = "{esc(T2[k][i])}";\n')
print(len(LANGS2) + 1, "more languages")
